import { Button } from '@mui/material';
import type { MeResponse } from '../../../../backend/src/types/api';
import HomeView from '../../../src/components/HomeView';
import SpotifyProfile from '../../../src/components/SpotifyProfile';

describe('HomeView', () => {
  const welcome = <HomeView accountAction={<Button variant="outlined" size="small">Sign in</Button>} welcomeAction={<Button variant="contained" size="large">Sign in with Spotify</Button>} />;

  it('signed out → welcomes the listener with a Spotify sign in', () => {
    cy.mount(welcome);
    cy.contains('h1', 'Every song has').should('be.visible');
    cy.contains('button', 'Sign in with Spotify').should('be.visible');
    cy.get('[data-cy="home"]').matchImage();
  });

  it('signed in → shows the connected profile in the welcome page', () => {
    cy.intercept('GET', '/api/me', { body: {
      clerkUserId: 'user_test', spotify: { id: 'spotify-test', displayName: 'Test Listener', imageUrl: null, profileUrl: null },
    } satisfies MeResponse }).as('me');
    cy.mount(<HomeView accountAction={<Button variant="outlined">Your account</Button>} profile={<SpotifyProfile />} />);
    cy.wait('@me');
    cy.contains('h2', 'Test Listener').should('be.visible');
    cy.get('[data-cy="home"]').matchImage();
  });

  it('mobile welcome → stacks the content without horizontal scrolling', () => {
    cy.viewport(390, 844);
    cy.mount(welcome);
    cy.contains('h1', 'Every song has').should('be.visible');
    cy.get('[data-cy="home"]').matchImage();
    cy.document().then((document) => expect(document.documentElement.scrollWidth).to.be.at.most(390));
  });
});
